     2	import type {OrchestratorHooks} from './chatOrchestrator.js';
     3	import type {AIProvider, MessageChunk} from '../types/ai.js';
     4	import type {ChatSession} from '../types/session.js';
     5	import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
     6	
     7	const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});
     8	const SENT_AT = '2026-01-01T00:00:00.000Z';
     9	
    10	const sessionWith = (content: string): ChatSession => ({
    11	  sessionId: 'test-session',
    12	  userId: 'user-1',
    13	  entries: [{role: 'user', content, timestamp: SENT_AT}],
    14	});
    15	
    16	const rejectingWith = (reason: unknown): AIProvider => ({
    17	  // eslint-disable-next-line require-yield
    18	  async *sendMessage(): AsyncGenerator<MessageChunk> {
    19	    throw reason;
    20	  },
    21	  async generateStructured<T>(): Promise<T> {
    22	    return {} as T;
    23	  },
    24	});
    25	
    26	const turnOutcome = async (reason: unknown) => {
    27	  const callOrder: string[] = [];
    28	  let seenError: Error | undefined;
    29	  const hooks: OrchestratorHooks = {
    30	    onError: async (_session, error) => {
    31	      callOrder.push('onError');
    32	      seenError = error;
    33	    },
    34	    afterSession: async () => {
    35	      callOrder.push('afterSession');
    36	    },
    37	  };
    38	
    39	  const orchestrator = createChatOrchestrator(rejectingWith(reason), promptBuilder, undefined, {hooks});
    40	  const outcome = await orchestrator.processMessage(sessionWith('hello')).then(
    41	    value => ({rejected: false, reason: value as unknown}),
    42	    (thrown: unknown) => ({rejected: true, reason: thrown})
    43	  );
    44	
    45	  return {
    46	    outcome,
    47	    callOrder,
    48	    isError: seenError instanceof Error,
    49	    message: seenError?.message,
    50	    cause: seenError?.cause,
    51	  };
    52	};
    53	
    54	describe('ChatOrchestrator onError on non-Error rejections', () => {
    55	  it('calls onError with an Error carrying the thrown string and runs afterSession while rethrowing', async () => {
    56	    const result = await turnOutcome('string boom');
    57	
    58	    expect(result).toEqual({
    59	      outcome: {rejected: true, reason: 'string boom'},
    60	      callOrder: ['onError', 'afterSession'],
    61	      isError: true,
    62	      message: 'string boom',
    63	      cause: 'string boom',
    64	    });
    65	  });
    66	
    67	  it('calls onError with an Error carrying a readable message when the stream rejects with a plain object', async () => {
    68	    const reason = {code: 503, detail: 'upstream down'};
    69	
    70	    const result = await turnOutcome(reason);
    71	
    72	    expect({
    73	      outcome: result.outcome,
    74	      callOrder: result.callOrder,
    75	      isError: result.isError,
    76	      hasMessage: typeof result.message === 'string' && result.message.length > 0,
    77	      cause: result.cause,
    78	    }).toEqual({
    79	      outcome: {rejected: true, reason},
    80	      callOrder: ['onError', 'afterSession'],
    81	      isError: true,
    82	      hasMessage: true,
    83	      cause: reason,
    84	    });
    85	  });
    86	});
